INSERT INTO `faq` (`id`, `question`, `answer`) VALUES
(1, 'Как подключить пакет услуг?', 'Обратитесь в офис продаж «Белтелеком», оставьте заявку на сайте или в приложении «Мой Белтелеком». Физическим лицам нужно иметь при себе паспорт и документы на помещение.'),
(2, 'Как подключить пакет без выезда в офис?', 'Оставьте заявку на сайте – к вам привезут оборудование и договор. Онлайн-заявка обрабатывается в течение 3 рабочих дней.'),
(3, 'Какие документы нужны для подключения?', 'Паспорт гражданина Республики Беларусь, вид на жительство или удостоверение беженца, а также документы, подтверждающие право пользования помещением.'),
(4, 'Сколько ждать подключения?', 'Онлайн-заявка обрабатывается в течение 3 рабочих дней. Точную дату и время визита специалиста согласуют при оформлении.'),
(5, 'Можно ли подключить пакет без визита в офис?', 'Да. Оставьте заявку на сайте – к вам привезут договор и оборудование.'),
(6, 'Можно ли подключить интернет в частном доме?', 'Да, если есть техническая возможность. Проверьте по адресу на сайте или по номеру 123.'),
(7, 'Можно ли подключить интернет в новостройке?', 'Да, если дом подключён к сети Белтелеком. Уточните в офисе продаж или по номеру 123.'),
(8, 'Как платить за пакеты услуг?', 'Наличными, картой на сайте Белтелеком, в банках, инфокиосках, отделениях «Белпочта», через Интернет-банкинг, картами экспресс-оплаты. Также доступен сервис «Обещанный платёж».'),
(9, 'Как оплатить пакет через интернет?', 'На сайте Белтелеком в разделе «Оплатить» – банковской картой Visa, MasterCard или БЕЛКАРТ.'),
(10, 'Что такое «Обещанный платёж»?', 'Это услуга, позволяющая пополнить счёт при нулевом балансе. Максимальная сумма – 20 рублей. Подтвердить платёж нужно в течение 5 суток.'),
(11, 'Что будет, если не оплатить вовремя?', 'При отрицательном балансе доступ ко всем услугам блокируется. Для возобновления нужно пополнить счёт.'),
(12, 'Где узнать свой баланс?', 'В «Кабинете пользователя», приложении «Мой Белтелеком» или по номеру 123.'),
(13, 'Как узнать свой номер договора?', 'Номер договора – это номер Приложения об оказании пакетов услуг. Узнать можно в офисе продаж или по номеру 123.'),
(14, 'Как оплатить услуги за другого человека?', 'Можно по номеру договора. Внесите номер лицевого счёта и сумму в любом платёжном терминале или на сайте.'),
(15, 'Можно ли вернуть ошибочно зачисленные деньги?', 'Да. Обратитесь в офис продаж с заявлением и квитанцией об оплате.'),
(16, 'Как сменить тарифный план?', 'Проверьте техническую возможность по номеру 123, затем смените тариф в «Кабинете пользователя», приложении «Мой Белтелеком» или в офисе продаж.'),
(17, 'Можно ли сменить тариф бесплатно?', 'Смена тарифного плана производится бесплатно. Оплата – по новому тарифу с момента переключения.'),
(18, 'Как перейти с отдельной услуги на пакет?', 'Обратитесь в офис продаж вашего района с паспортом. В составе пакета услуги дешевле, чем по отдельности.'),
(19, 'Можно ли вернуться на отдельные услуги?', 'Да, для этого нужно обратиться в офис продаж. Услуги будут предоставляться по отдельным тарифам.'),
(20, 'Как перейти на ЯСНА 500?', 'Проверьте техническую возможность по номеру 123. Если доступна технология xPON – переключение возможно.'),
(21, 'Какие тарифы самые популярные?', 'Чаще всего выбирают ЯСНА 200 new, ЯСНА 500 и Семейный 10 – оптимальное соотношение цены и скорости.'),
(22, 'Чем отличается ЯСНА от Семейного?', 'ЯСНА работает по технологии xPON (высокая скорость), Семейный – по xDSL (классическая телефонная линия).'),
(23, 'Что такое технология xPON?', 'Это пассивная оптическая сеть – оптоволокно до квартиры. Обеспечивает высокую скорость и качество связи.'),
(24, 'Что такое ZALA?', 'ZALA – торговая марка услуг телевидения Белтелеком: интерактивное, SMART и эфирное ТВ.'),
(25, 'Что такое SMART ZALA?', 'SMART ZALA – сервис для просмотра ТВ на планшетах, смартфонах и Smart TV. Требует доступа в интернет.'),
(26, 'Какие каналы входят в пакет?', 'Информация о телеканалах размещена в разделах «Интерактивное», «SMART» и «Эфирное» на сайте Белтелеком.'),
(27, 'Что такое «ЯСНА 100 Дом + Дача»?', 'Тариф для двух адресов: основной (город) и дача. Работает по технологии Wi-Fi с едиными реквизитами доступа.'),
(28, 'Что такое «ЯСНА Лайт»?', 'Бюджетный тариф с минимальной скоростью до 5 Мбит/с, интернет и ТВ по низкой цене.'),
(29, 'Что такое «Умный дом»?', 'Услуга управления устройствами в доме через мобильное приложение: датчики движения, температуры, протечки воды и т. д.'),
(30, 'Что такое «Видеоконтроль»?', 'Услуга видеонаблюдения для многоквартирных домов и частных домов, с просмотром онлайн и архивом 30 суток.'),
(31, 'Что такое «Видеодомофон»?', 'Услуга видеосвязи с посетителями через домофон с видеокамерой.'),
(32, 'Какое оборудование предоставляется?', 'Модем, Wi-Fi роутер, ТВ-приставка SMART ZALA – в пользование без дополнительной оплаты на срок действия договора.'),
(33, 'Что делать, если оборудование сломалось?', 'Обратитесь в службу поддержки по номеру 123. Если поломка не по вине абонента – заменят бесплатно.'),
(34, 'В каких случаях возможна замена терминала?', 'Замена исправного терминала не проводится, кроме случаев смены низкоскоростных тарифов на высокоскоростные.'),
(35, 'Можно ли купить роутер в рассрочку?', 'Да, устройства можно приобрести в рассрочку в BELTELECOM SHOP.'),
(36, 'Как настроить Wi-Fi?', 'При первичном подключении настройка Wi-Fi бесплатна. Повторная настройка – платная услуга.'),
(37, 'Какой роутер выбрать?', 'Рекомендуем модели с поддержкой двух диапазонов (2,4 и 5 ГГц). Для многоквартирных домов – Wi-Fi 6.'),
(38, 'Как усилить сигнал Wi-Fi?', 'Разместите роутер в центре квартиры, на высоте. Избегайте соседства с микроволновкой и металлическими предметами.'),
(39, 'Что делать, если не работает интернет?', 'Проверьте баланс, перезагрузите роутер. Если не помогло – позвоните по номеру 123.'),
(40, 'Что делать, если низкая скорость?', 'Проверьте количество подключённых устройств и работу роутера. При необходимости обратитесь по номеру 123.'),
(41, 'Как зайти в «Кабинет пользователя»?', 'Логин и первоначальный пароль указаны в бланке заказа. Вход – на сайте my.beltelecom.by или в приложении «Мой Белтелеком».'),
(42, 'Что делать, если забыл пароль?', 'Воспользуйтесь функцией восстановления пароля или обратитесь в службу поддержки по номеру 123.'),
(43, 'Какие возможности у «Кабинета пользователя»?', 'Просмотр баланса, смена тарифа, подключение и отключение услуг, пополнение счёта, статистика использования.'),
(44, 'Как заблокировать услугу?', 'Добровольная блокировка (бесплатно) – на 15 или 30 дней, суммарно не более 30 дней в год. Платная блокировка – на 15, 30, 45, 90 дней.'),
(45, 'Что такое блокировка на 180 дней?', 'Доступна для пакетов ЯСНА (кроме ЯСНА Лайт) при подключении в дачном кооперативе, если есть второе городское подключение.'),
(46, 'Можно ли досрочно разблокировать услугу?', 'Да, по желанию абонента. Неиспользованные дни не возвращаются, сервис считается оказанным в полном объёме.'),
(47, 'Как разблокировать интернет?', 'Пополните счёт до положительного баланса. Доступ восстановится автоматически.'),
(48, 'Как связаться со службой поддержки?', 'По номеру 123 (круглосуточно), через «Кабинет пользователя» или приложение «Мой Белтелеком».'),
(49, 'Где найти офис продаж?', 'Адреса всех офисов продаж размещены на сайте Белтелеком в разделе «Офисы продаж».'),
(50, 'Как вызвать специалиста на дом?', 'Позвоните по номеру 123 или оставьте заявку на сайте. Специалист приедет в согласованное время.'),
(51, 'Сколько стоит вызов специалиста?', 'При восстановлении доступа к услугам плата за вызов представителя не взимается.'),
(52, 'Какие действуют акции?', 'Узнать доступные акции можно в офисе продаж по месту оказания услуг или на сайте.'),
(53, 'Есть ли скидки для пенсионеров?', 'Пакет «ЯСНА Социальный» предоставляется инвалидам, многодетным семьям, ветеранам ВОВ и другим льготным категориям.'),
(54, 'Как подключить «ЯСНА Социальный»?', 'Обратитесь в офис продаж с документами, подтверждающими право на льготу.'),
(55, 'Можно ли расторгнуть договор?', 'Да. Обратитесь в офис продаж с паспортом. Оборудование нужно вернуть.'),
(56, 'Что делать при переезде?', 'Обратитесь в офис продаж с паспортом. Если по новому адресу есть техническая возможность – услуги переключат.'),
(57, 'Можно ли оформить договор на другого человека?', 'Да, при наличии доверенности или личного присутствия владельца.'),
(58, 'Можно ли пользоваться Wi-Fi в публичных местах?', 'Да, если услуга входит в ваш пакет. Найдите точку Beltelecom или byfly Wi-Fi, введите логин и пароль из бланка заказа.'),
(59, 'Что такое «Кредит доверия»?', 'Услуга для абонентов с тарифами от 200 Мбит/с, позволяющая продолжить пользование при отрицательном балансе.'),
(60, 'Что такое «Турбо кнопка»?', 'Услуга временного увеличения скорости интернета при наличии технической возможности.'),
(61, 'Что такое «Родительский контроль»?', 'Услуга фильтрации нежелательного контента – порнографии, насилия, наркотиков и вредоносных сайтов.'),
(62, 'Что такое «Антивирусная защита»?', 'Дополнительная услуга от byfly на базе антивирусов «Лаборатории Касперского» с ежесуточной оплатой.'),
(63, 'Что такое «Статический IP-адрес»?', 'Дополнительная услуга предоставления постоянного IP-адреса для безлимитных тарифных планов.'),
(64, 'Как отказаться от услуги?', 'Обратитесь в офис продаж с паспортом или в службу поддержки по номеру 123.'),
(65, 'Что такое «Видеопортал»?', 'Дополнительная услуга для просмотра фильмов и телепередач через интернет.'),
(66, 'Что такое «SMS-оповещение»?', 'Услуга уведомления о приближении к порогу отключения. Стоимость – 0,30 руб. в месяц.'),
(67, 'Как проверить скорость интернета?', 'На сайте speedtest.by или через сервис Speedtest. Запустите тест и дождитесь результата.'),
(68, 'Как настроить SMART ZALA?', 'Скачайте приложение ZALA, введите логин и пароль из бланка заказа. Работает на смартфонах, планшетах, Smart TV.'),
(69, 'Что такое byfly?', 'Byfly – торговая марка услуги доступа в интернет от Белтелеком.');
INSERT INTO `tariffs` (`id`, `name`, `price`, `speed`, `phone`, `tv`, `video_control`, `technology`, `is_archive`, `line`) VALUES
(1, 'ЯСНА 500', 67.50, '500/250 Мбит/с', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено»', NULL, 'PON', 0, 'ЯСНА'),
(2, 'ЯСНА 500 SMART', 67.50, '500/250 Мбит/с', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'SMART-телевидение на условиях тарифного плана «Канапа ТВ» с выдачей телевизионной приставки SMART ZALA', NULL, 'PON', 0, 'ЯСНА'),
(3, 'ЯСНА 200 new', 49.00, '200/100 Мбит/с', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено»', NULL, 'PON', 0, 'ЯСНА'),
(4, 'ЯСНА 200 SMART', 49.00, '200/100 Мбит/с', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'SMART-телевидение на условиях тарифного плана «Канапа ТВ» с выдачей телевизионной приставки SMART ZALA', NULL, 'PON', 0, 'ЯСНА'),
(5, 'ЯСНА 200 Промо', 52.00, '200/100 Мбит/с', NULL, 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено»', NULL, 'PON', 0, 'ЯСНА'),
(6, 'ЯСНА 200+Кино', 52.00, '200/100 Мбит/с', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено», доступ к онлайн-кинотеатрам Иви Лайт и Wink Лайт', NULL, 'PON', 0, 'ЯСНА'),
(7, 'ЯСНА 200 Видеоконтроль', 52.00, '200/100 Мбит/с', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено»', 'Доступ к услуге «Видеоконтроль»', 'PON', 0, 'ЯСНА'),
(8, 'ЯСНА 200 SMART Видеоконтроль', 52.00, '200/100 Мбит/с', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'SMART-телевидение на условиях тарифного плана «Канапа ТВ» с выдачей телевизионной приставки SMART ZALA', 'Доступ к услуге «Видеоконтроль»', 'PON', 0, 'ЯСНА'),
(9, 'ЯСНА 100 Дом + Дача', 51.50, '100/50 Мбит/с и нелимитируемый доступ по технологии Wi-Fi', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено», цифровое эфирное телевидение на условиях тарифного плана «Стандарт ТВ»', NULL, 'PON', 0, 'ЯСНА'),
(10, 'ЯСНА 100 + Кино', 46.00, '100/50 Мбит/с и нелимитируемый доступ по технологии Wi-Fi', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено», доступ к онлайн-кинотеатрам Иви Лайт и Wink Лайт', NULL, 'PON', 0, 'ЯСНА'),
(11, 'ЯСНА 100 Видеоконтроль', 43.50, '100/50 Мбит/с и нелимитируемый доступ по технологии Wi-Fi', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено»', 'Доступ к услуге «Видеоконтроль»', 'PON', 0, 'ЯСНА'),
(12, 'ЯСНА 100 SMART Видеоконтроль', 44.00, '100/50 Мбит/с и нелимитируемый доступ по технологии Wi-Fi', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'SMART-телевидение на условиях тарифного плана «Канапа ТВ» и дополнительных пакетов «Премиум» и «Больше ТВ»', 'Доступ к услуге «Видеоконтроль»', 'PON', 0, 'ЯСНА'),
(13, 'ЯСНА Лайт', 23.50, 'до 5 Мбит/с (нелимитируемый доступ по технологии Wi-Fi)', 'Неограниченная продолжительность телефонных соединений по сети Белтелеком и услуга Идентификация линии вызывающего абонента (CLIP)', 'Интерактивное телевидение на условиях тарифного плана «ZALA: все включено»', NULL, 'PON', 0, 'ЯСНА'),
